const x=$json;
if(!['checkout_start','checkout_confirm'].includes(x.operation))
 throw new Error('checkout_invalid_operation');
if(typeof x.customer_id!=='string'||!x.customer_id.trim())
 throw new Error('checkout_missing_customer');
if(!['facebook','whatsapp','instagram','internal'].includes(x.channel))
 throw new Error('checkout_invalid_channel');
return [{json:{
 ...x,store_id:x.store_id||'default',
 action_id:x.action_id||`${x.customer_id}:${x.operation}:${Date.now()}`
}}];

// WF-10 must be the real authorization boundary.
// This node only asserts that the upstream caller supplied the required
// authorization result; it does not grant permission.
const x=$json;
if(x.authorization_result && x.authorization_result!=='allow')
 throw new Error('checkout_not_authorized');
return [{json:{...x,authorization_asserted:true}}];

const x=$json;
return [{json:{
 operation:'checkout_validate',
 customer_id:x.customer_id,
 channel:x.channel,
 store_id:x.store_id,
 action_id:x.action_id,
 // WF-20 resolves protected cart session internally.
 cart_reference_resolution:'internal_wf20_only',
 require_live_product_validation:true,
 require_live_stock_validation:true,
 require_live_price_validation:true,
 require_live_coupon_validation:true,
 payment_method:'cod',
 create_order:false
}}];

const req=$('Prepare WF-20 Checkout Validation').first().json;
const r=$json;
if(r.commerce_status==='unavailable'){
 return [{json:{
  success:false,operation:'checkout_validate',customer_id:req.customer_id,
  commerce_status:'unavailable',verified:false,checkout_snapshot:null,
  error:{code:'COMMERCE_UNAVAILABLE',order_creation_allowed:false,
    fallback:'preserve_purchase_intent_and_customer_details'}
 }}];
}
return [{json:{
 success:Boolean(r.success),
 operation:req.operation==='checkout_validate'?'checkout_start':req.operation,
 customer_id:req.customer_id,
 commerce_status:r.commerce_status||'available',
 verified:Boolean(r.verified && r.success),
 checkout_snapshot:r.checkout_snapshot||null,
 error:r.error||null
}}];

const x=$json;
if(x.success && !x.verified) throw new Error('checkout_success_without_verification');
if(x.success && x.commerce_status!=='available')
 throw new Error('checkout_success_without_live_commerce');
if(x.success && !x.checkout_snapshot)
 throw new Error('checkout_missing_snapshot');

if(x.success){
 const s=x.checkout_snapshot;
 const required=['cart_reference','currency','items','subtotal','discount_total','shipping_total','total','payment_method','snapshot_id'];
 for(const k of required) if(s[k]===undefined || s[k]===null) throw new Error(`checkout_snapshot_missing_${k}`);
 if(s.payment_method!=='cod') throw new Error('checkout_unexpected_payment_method');
 if(s.order_created===true) throw new Error('checkout_must_not_create_order');
}
return [{json:x}];
